// Normalize inbound message + choose a keyword-based fixed reply.
const CHECKOUT = 'https://ramannaiknaware.graphy.com/courses/DPharm-1st-year-Pharmaceutics-Complete-Notes-69883bcbc8266f1243b25fed';
const COMBO = 'https://ramannaiknaware.graphy.com/courses/DPharm-1st-Year-Combo-1777537319930-69f311273e897b00ec94531a';
const SAMPLE = 'https://drive.google.com/file/d/1rHrKPCAWHzfMvzjK2drLs-l34tzHswcT/view?usp=sharing';

function replyFor(text) {
  const t = String(text || '').toLowerCase();
  if (/(price|₹|cost|kitne|kimat|paisa|rate)/.test(t)) return `💰 Pricing:\n• Early-bird ₹69 (first 30)\n• Regular ₹99\n• Combo me aur bachat!\nBuy 👉 ${CHECKOUT}`;
  if (/(syllabus|chapter|topic|cover|content)/.test(t)) return `📚 Notes MSBTE ER20-11T Pharmaceutics ke exact chapters cover karti hain — Dosage Forms, Sterile Formulations, Packaging, Stability + diagrams.\nBuy 👉 ${CHECKOUT}`;
  if (/(sample|demo|free|trial)/.test(t)) return `📥 FREE sample: ${SAMPLE}\nPasand aaye to ₹69 me poori notes 👉 ${CHECKOUT}`;
  if (/(buy|kharid|link|payment|purchase|order)/.test(t)) return `🛒 Secure checkout (UPI/Card/NetBanking):\n${CHECKOUT}\nCombo 👉 ${COMBO}`;
  return `Hi! 👋 Main ManPharma helper hoon. Type karo:\n• \"price\" — kimat\n• \"sample\" — free demo\n• \"syllabus\" — kya cover hota hai\n• \"buy\" — kharidne ka link`;
}

const out = [];
for (const item of $input.all()) {
  let contact, channel, text, name;
  if (item.json.message) {
    const m = item.json.message;
    contact = String(m.chat.id);
    channel = 'telegram';
    text = m.text || '';
    name = (m.from && (m.from.first_name || m.from.username)) || 'Student';
  } else {
    const b = item.json.body || item.json;
    contact = String(b.contact || b.from || b.sender || '');
    channel = (b.channel || 'whatsapp').toLowerCase();
    text = b.text || b.message || '';
    name = b.name || 'Student';
  }
  out.push({ json: { contact, channel, name, incoming: text, message: replyFor(text) } });
}
return out;
